const apiKey = process.env.CROSSMINT_API_KEY || "";

const requestBody = {
  recipient: "email:user@example.com:polygon-amoy",
  metadata: {
    name: "My NFT",
    description: "Minted via Crossmint API",
    image: "https://example.com/nft.png"
  }
};

async function writeResponse(payload) {
  fs.writeFileSync(RESPONSE_PATH, JSON.stringify(payload, null, 2));
}

async function mintNft() {
  if (!apiKey) {
    await writeResponse({
      error: "Missing CROSSMINT_API_KEY",
      message: "Set CROSSMINT_API_KEY to a server-side key starting with 'sk_'."
    });
    return;
  }

  if (!apiKey.startsWith("sk_")) {
    await writeResponse({
      error: "Invalid API key",
      message: "Crossmint minting requires a server-side API key starting with 'sk_'."
    });
    return;
  }

  try {
    const response = await fetch(`${BASE_URL}${API_PATH}`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-client-secret": apiKey
      },
      body: JSON.stringify(requestBody)
    });

    const responseBody = await response.json().catch(() => ({}));
    await writeResponse({
      status: response.status,
      ok: response.ok,
      data: responseBody
    });
  } catch (error) {
    await writeResponse({
      error: "Request failed",
      message: error.message
    });

